// LOAD condition for 74194: s1 = 1, s0 = 1// SHIFT condition: s1 = 0, s0 = 1// NO CHANGE condition: s1 = 0, s0 = 0module Supp_9_16 (  output [3: 0] accum_sum,   output carry,   input [3: 0] Data_in, Addr_in,   input SIR, SIL, CS, WE, s1, s0, count, Load, select, STB, clock, preset, clear, VCC, GND);  wire B4 = Data_in[3];	// Data world to memory  wire B3 = Data_in[2];    wire B2 = Data_in[1];    wire B1 = Data_in[0];  wire S4, S3, S2, S1;  wire D4, D3, D2, D1;  wire S4b = ~S4;	// Inverters  wire S3b = ~S3;  wire S2b = ~S2;  wire S1b = ~S1;  wire D = Addr_in[3];	// For parallel load of address counter  wire C = Addr_in[2];  wire B = Addr_in[1];  wire A = Addr_in[0];  wire Ocar, Y1, Y2, Y3, Y4, QA, QB, QC, QD, A3, A2, A1, A0;  assign accum_sum = {D4, D3, D2, D1};   Flip_flop_7474 	M0 (Ocar, carry, clock, preset, clear);   Adder_7483 	M1 (D4, D3, D2, D1, carry, S4b, S3b, S2b, S1b, QD, QC, QB, QA, Ocar, VCC, GND);  Mux_74157 	M2 (Y4, Y3, Y2, Y1, QD, QC, QB, QA, B4, B3, B2, B1, select, STB);  Counter_74161 	M3 (A3, A2, A1, A0, COUT, D, C, B, A, count, count, Load, clock, clear);  RAM_74189 	M4 (S4, S3, S2, S1, Y4, Y3, Y2, Y1, A3, A2, A1, A0, CS, WE);  Reg_74194	M5 (QD, QC, QB, QA, D4, D3, D2, D1, Ocar, SIL, s1, s0, clock, clear);endmodulemodule t_Supp_9_16 ();  wire [3: 0] sum;  wire carry;  reg [3: 0] Data_in, Addr_in;   reg SIR, SIL, CS, WE, s1, s0, count, Load, select, STB, clock, preset, clear;  supply1 VCC;  supply0 GND;  wire [3: 0] RAM_0 = M0.M4.RAM[0];  wire [3: 0] RAM_1 = M0.M4.RAM[1];  wire [3: 0] RAM_2 = M0.M4.RAM[2];  wire [3: 0] RAM_3 = M0.M4.RAM[3];  wire [3: 0] RAM_4 = M0.M4.RAM[4];  wire [3: 0] RAM_5 = M0.M4.RAM[5];  wire [3: 0] RAM_6 = M0.M4.RAM[6];  wire [3: 0] RAM_7 = M0.M4.RAM[7];  wire [3: 0] RAM_8 = M0.M4.RAM[8];  wire [3: 0] RAM_9 = M0.M4.RAM[9];  wire [3: 0] RAM_10 = M0.M4.RAM[10];  wire [3: 0] RAM_11 = M0.M4.RAM[11];  wire [3: 0] RAM_12= M0.M4.RAM[12];  wire [3: 0] RAM_13 = M0.M4.RAM[13];  wire [3: 0] RAM_14 = M0.M4.RAM[14];  wire [3: 0] RAM_15 = M0.M4.RAM[15];  wire [4: 1] word = {M0.S4b, M0.S3b,M0.S2b, M0.S1b}; wire [4: 1] mux_out = { M0.Y4, M0.Y3, M0.Y2, M0.Y1}; wire [4: 1] Reg_Output = {M0.QD, M0.QC, M0.QB, M0.QA}; Supp_9_16 M0 (sum, carry, Data_in, Addr_in, SIR, SIL, CS, WE, s1, s0, count, Load,   select, STB,   clock, preset, clear, VCC, GND);  integer k;  initial #600 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial fork    #10 begin preset = 1; clear = 0; s1 = 0; s0 = 0; Load = 1; count = 0; CS = 1; WE = 1; STB = 0;  end    // initialize memory    #10 begin k = 0; repeat (16) begin M0.M4.RAM[k] = 4'hf; k = k + 1; end end    #20 begin Data_in = 4'hf; Addr_in  = 0; select = 1; end    #30 begin clear = 1; WE = 0; end      // load memory    #40 begin       count = 1;       CS = 0;      begin         repeat (16) @ (negedge clock) Data_in = Data_in + 1;            count = 0;        @ (negedge clock) CS = 1;      end        end     #200 count = 1;				// Establish address    #240 count = 0;    #250 WE = 1;    #260 CS = 0;					// Read from memory    #280 clear = 0;    #290 clear = 1;    #300 count = 1;				// Establish address     #340 begin s1 = 1; s0 = 1; count = 0; end    #390 CS = 0;    #400 clear = 0;				// Clear the registers    #410 clear = 1;    #420 begin count = 1; CS = 0; end		// Accumulate values    #490 begin count = 0; CS = 1; end  joinendmodulemodule Flip_flop_7474 (output reg Q, input D, CLK, preset, clear); always @ (posedge CLK, negedge preset , negedge clear)if (!preset)     	Q <= 1'b1;else if (!clear) 	Q <= 1'b0;else 	Q <= D;endmodulemodule Adder_7483 (  output S4, S3, S2, S1, C4,  input A4, A3, A2, A1, B4, B3, B2, B1, C0, VCC, GND);// Note: connect VCC and GND to supply1 and supply0 in the test bench  wire [4: 1] sum;  wire [4: 1] A = {A4, A3, A2, A1};  wire [4: 1] B = {B4, B3, B2, B1};  assign S4 = sum[4];  assign S3 = sum[3];  assign S2 = sum[2];  assign S1 = sum[1];  assign {C4, sum} = A + B + C0;endmodulemodule Mux_74157 (  output reg Y1, Y2, Y3, Y4,   input A1, A2, A3, A4, B1, B2, B3, B4, SEL, STB);  wire [4: 1] In_A = {A1, A2, A3, A4};  wire [4: 1] In_B = {B1, B2, B3, B4};  always @ (In_A, In_B, SEL, STB)    if (STB) {Y1, Y2, Y3, Y4} = 4'b0;    else if (SEL) {Y1, Y2, Y3, Y4} = In_B;    else {Y1, Y2, Y3, Y4} = In_A;endmodulemodule Counter_74161 (  output  	QD, QC, QB, QA,		// Data output  output 	COUT,			// Output carry  input	 	D, C, B, A,		// Data input   input 	P, T, 			// Active high to count			L, 			// Active low to load			CK, 			// Positive edge sensitive			CLR			// Active low to clear);reg [3: 0] A_count;assign QD = A_count[3];assign QC = A_count[2];assign QB = A_count[1];assign QA = A_count[0];assign COUT = ((P == 1) && (T == 1) && (L == 1) && (A_count == 4'b1111));
always @ (posedge CK, negedge CLR)if (CLR == 0) 						A_count <= 4'b0000;else if (L == 0)					A_count <= {D, C, B, A};else if ((P == 1) && (T == 1)) 	A_count <= A_count + 1'b1;else 								A_count <= A_count;	// redundant statementendmodulemodule RAM_74189 (output S4, S3, S2, S1, input D4, D3, D2, D1, A3, A2, A1, A0, CS, WE);// Note: active-low CS and WE  wire [3: 0] 	address = {A3, A2, A1, A0};   reg [3: 0] 	RAM [0: 15];			// 16 x 4 memory  wire [4: 1] 	Data_in = { D4, D3, D2, D1};	// Input word  tri [4: 1] 		Data;				// Output data word, three-state output  assign S1 = Data[1];			// Output bits  assign S2 = Data[2];  assign S3 = Data[3];  assign S4 = Data[4];  always @ (Data_in, address, CS, WE) if (~CS && ~WE) RAM[address] = Data_in;  assign Data = (~CS && WE) ? ~RAM[address] : 4'bz; 	// Note complement of data wordendmodulemodule Reg_74194 (  output reg 	QA, QB, QC, QD,  input 		A, B, C, D, SIR, SIL, s1, s0, CK, CLR);  always @ (posedge CK, negedge CLR)    if (!CLR) {QA, QB, QC, QD} <= 4'b0;    else case ({s1, s0})      2'b00:	{QA, QB, QC, QD} <= {QA, QB, QC, QD};      2'b01:	{QA, QB, QC, QD} <= {SIR, QA, QB, QC};      2'b10:	{QA, QB, QC, QD} <= {QB, QC, QD, SIL};      2'b11:	{QA, QB, QC, QD} <= {A, B, C, D};    endcaseendmodule